 10→/**
 11→ * Central Prometheus metrics registry and collector.
 12→ * Exposes both event-driven counters (incremented by controllers/services)
 13→ * and gauge metrics polled from the database every 30 seconds.
 14→ */
 15→@Injectable()
 16→export class MetricsService implements OnModuleInit {
 17→  private readonly logger = new Logger(MetricsService.name);
 18→  readonly registry: client.Registry;
 19→  private collectInterval: ReturnType<typeof setInterval> | null = null;
 20→
 21→  // --- Gauges (DB-polled state) ---
 22→  readonly usersTotal: client.Gauge;
 23→  readonly filesTotal: client.Gauge;
 24→  readonly storageBytesTotal: client.Gauge;
 25→  readonly ipnsEntriesTotal: client.Gauge;
 26→  readonly republishScheduleTotal: client.Gauge;
 27→
 28→  // --- Counters (event-driven) ---
 29→  readonly fileUploads: client.Counter;
 30→  readonly fileUploadBytes: client.Counter;
 31→  readonly fileDownloads: client.Counter;
 32→  readonly fileUnpins: client.Counter;
 33→  readonly ipnsPublishes: client.Counter;
 34→  readonly ipnsResolves: client.Counter;
 35→  readonly republishRuns: client.Counter;
 36→  readonly republishEntriesProcessed: client.Counter;
 37→  readonly authLogins: client.Counter;
 38→
 39→  // --- Counters (delegated routing) ---
 40→  readonly delegatedRoutingRequests: client.Counter;
 41→  readonly delegatedRoutingFallbacks: client.Counter;
 42→
 43→  // --- Histograms ---
 44→  readonly httpRequestDuration: client.Histogram;
 45→  readonly ipfsIpnsDuration: client.Histogram;
 46→  readonly republishBatchDuration: client.Histogram;
 47→  readonly ipnsResolveDuration: client.Histogram;
 48→  readonly ipnsPublishDuration: client.Histogram;
 49→
 50→  constructor(
 51→    @InjectRepository(PinnedCid)
 52→    private readonly pinnedCidRepository: Repository<PinnedCid>,
 53→    @InjectRepository(FolderIpns)
 54→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 55→    @InjectRepository(User)
 56→    private readonly userRepository: Repository<User>,
 57→    @InjectRepository(IpnsRepublishSchedule)
 58→    private readonly republishScheduleRepository: Repository<IpnsRepublishSchedule>
 59→  ) {
 60→    this.registry = new client.Registry();
 61→    this.registry.setDefaultLabels({ app: 'cipherbox-api' });
 62→
 63→    // Gauges
 64→    this.usersTotal = new client.Gauge({
 65→      name: 'cipherbox_users_total',
 66→      help: 'Total registered users',
 67→      registers: [this.registry],
 68→    });
 69→
 70→    this.filesTotal = new client.Gauge({
 71→      name: 'cipherbox_files_total',
 72→      help: 'Total pinned files across all users',
 73→      registers: [this.registry],
 74→    });
 75→
 76→    this.storageBytesTotal = new client.Gauge({
 77→      name: 'cipherbox_storage_bytes_total',
 78→      help: 'Total storage used across all users in bytes',
 79→      registers: [this.registry],
 80→    });
 81→
 82→    this.ipnsEntriesTotal = new client.Gauge({
 83→      name: 'cipherbox_ipns_entries_total',
 84→      help: 'Total IPNS entries by record type',
 85→      labelNames: ['record_type'],
 86→      registers: [this.registry],
 87→    });
 88→
 89→    this.republishScheduleTotal = new client.Gauge({
 90→      name: 'cipherbox_republish_schedule_total',
 91→      help: 'IPNS republish schedule entries by status',
 92→      labelNames: ['status'],
 93→      registers: [this.registry],
 94→    });
 95→
 96→    // Counters
 97→    this.fileUploads = new client.Counter({
 98→      name: 'cipherbox_file_uploads_total',
 99→      help: 'Total file uploads',
100→      registers: [this.registry],
101→    });
102→
103→    this.fileUploadBytes = new client.Counter({
104→      name: 'cipherbox_file_upload_bytes_total',
105→      help: 'Total bytes uploaded',
106→      registers: [this.registry],
107→    });
108→
109→    this.fileDownloads = new client.Counter({
110→      name: 'cipherbox_file_downloads_total',
111→      help: 'Total file downloads',
112→      registers: [this.registry],
113→    });
114→
115→    this.fileUnpins = new client.Counter({
116→      name: 'cipherbox_file_unpins_total',
117→      help: 'Total file unpins',
118→      registers: [this.registry],
119→    });
120→
121→    this.ipnsPublishes = new client.Counter({
122→      name: 'cipherbox_ipns_publishes_total',
123→      help: 'Total IPNS publishes',
124→      labelNames: ['type'],
125→      registers: [this.registry],
126→    });
127→
128→    this.ipnsResolves = new client.Counter({
129→      name: 'cipherbox_ipns_resolves_total',
130→      help: 'Total IPNS resolves',
131→      labelNames: ['source'],
132→      registers: [this.registry],
133→    });
134→
135→    this.republishRuns = new client.Counter({
136→      name: 'cipherbox_republish_runs_total',
137→      help: 'Total republish cron runs',
138→      registers: [this.registry],
139→    });
140→
141→    this.republishEntriesProcessed = new client.Counter({
142→      name: 'cipherbox_republish_entries_processed_total',
143→      help: 'Total republish entries processed',
144→      labelNames: ['result'],
145→      registers: [this.registry],
146→    });
147→
148→    this.authLogins = new client.Counter({
149→      name: 'cipherbox_auth_logins_total',
150→      help: 'Total successful logins',
151→      labelNames: ['method', 'new_user'],
152→      registers: [this.registry],
153→    });
154→
155→    // Delegated routing counters
156→    this.delegatedRoutingRequests = new client.Counter({
157→      name: 'cipherbox_delegated_routing_requests_total',
158→      help: 'Total delegated routing requests by operation, backend, and outcome',
159→      labelNames: ['operation', 'backend', 'outcome'],
160→      registers: [this.registry],
161→    });
162→
163→    this.delegatedRoutingFallbacks = new client.Counter({
164→      name: 'cipherbox_delegated_routing_fallbacks_total',
165→      help: 'Times the primary routing backend failed and fallback was used',
166→      labelNames: ['operation'],
167→      registers: [this.registry],
168→    });
169→
170→    // Histograms
171→    this.httpRequestDuration = new client.Histogram({
172→      name: 'cipherbox_http_request_duration_seconds',
173→      help: 'HTTP request duration in seconds',
174→      labelNames: ['method', 'route', 'status_code'],
175→      buckets: [0.01, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10],
176→      registers: [this.registry],
177→    });
178→
179→    this.ipfsIpnsDuration = new client.Histogram({
180→      name: 'cipherbox_ipfs_ipns_duration_seconds',
181→      help: 'Duration of IPFS/IPNS operations in seconds',
182→      labelNames: ['operation', 'result', 'source'] as const,
183→      buckets: [0.001, 0.005, 0.01, 0.025, 0.05, 0.1, 0.25, 0.5, 1, 2.5, 5, 10, 20, 30],
184→      registers: [this.registry],
185→    });
186→
187→    this.republishBatchDuration = new client.Histogram({
188→      name: 'cipherbox_republish_batch_duration_seconds',
189→      help: 'Duration of TEE republish batch processing in seconds',
190→      labelNames: ['tee_provider', 'result'] as const,
191→      buckets: [1, 2.5, 5, 10, 15, 30, 45, 60, 90, 120],
192→      registers: [this.registry],
193→    });
194→
195→    this.ipnsResolveDuration = new client.Histogram({
196→      name: 'cipherbox_ipns_resolve_duration_seconds',
197→      help: 'IPNS resolve duration in seconds (end-to-end including fallback)',
198→      labelNames: ['source', 'outcome'],
199→      buckets: [0.05, 0.1, 0.25, 0.5, 1, 2, 5, 10, 30],
200→      registers: [this.registry],
201→    });
202→
203→    this.ipnsPublishDuration = new client.Histogram({
204→      name: 'cipherbox_ipns_publish_duration_seconds',
205→      help: 'IPNS publish duration to routing provider in seconds',
206→      labelNames: ['outcome'],
207→      buckets: [0.1, 0.25, 0.5, 1, 2, 5, 10, 30, 60],
208→      registers: [this.registry],
209→    });
210→  }
211→
212→  async onModuleInit(): Promise<void> {
213→    // Attempt an immediate collection; log and continue if DB isn't ready yet
214→    await this.collectGauges().catch((err: unknown) => {
215→      this.logger.warn(
216→        `Initial gauge collection failed: ${err instanceof Error ? err.message : String(err)}`
217→      );
218→    });
219→    this.collectInterval = setInterval(() => {
220→      this.collectGauges().catch((err: unknown) => {
221→        this.logger.warn(
222→          `Gauge collection failed: ${err instanceof Error ? err.message : String(err)}`
223→        );
224→      });
225→    }, 30_000);
226→    this.logger.log('Prometheus metrics initialized (collecting gauges every 30s)');
227→  }
228→
229→  onModuleDestroy(): void {
230→    if (this.collectInterval) {
231→      clearInterval(this.collectInterval);
232→    }
233→  }
234→
235→  async getMetrics(): Promise<string> {
236→    return this.registry.metrics();
237→  }
238→
239→  getContentType(): string {
240→    return this.registry.contentType;
241→  }
242→
243→  private async collectGauges(): Promise<void> {
244→    const [userCount, fileStats, ipnsByType, republishByStatus] = await Promise.all([
245→      this.userRepository.count(),
246→      this.pinnedCidRepository
247→        .createQueryBuilder('pin')
248→        .select('COUNT(*)', 'count')
249→        .addSelect('COALESCE(SUM(pin.size_bytes), 0)', 'totalBytes')
250→        .getRawOne<{ count: string; totalBytes: string }>(),
251→      this.folderIpnsRepository
252→        .createQueryBuilder('ipns')
253→        .select('ipns.record_type', 'recordType')
254→        .addSelect('COUNT(*)', 'count')
255→        .groupBy('ipns.record_type')
256→        .getRawMany<{ recordType: string; count: string }>(),
257→      this.republishScheduleRepository
258→        .createQueryBuilder('sched')
259→        .select('sched.status', 'status')
260→        .addSelect('COUNT(*)', 'count')
261→        .groupBy('sched.status')
262→        .getRawMany<{ status: string; count: string }>(),
263→    ]);
264→
265→    this.usersTotal.set(userCount);
266→    this.filesTotal.set(parseInt(fileStats?.count ?? '0', 10));
267→    this.storageBytesTotal.set(parseInt(fileStats?.totalBytes ?? '0', 10));
268→
269→    // Reset IPNS gauges before setting to avoid stale labels
270→    this.ipnsEntriesTotal.reset();
271→    for (const row of ipnsByType) {
272→      this.ipnsEntriesTotal.labels(row.recordType).set(parseInt(row.count, 10));
273→    }
274→
275→    // Reset republish gauges before setting
276→    this.republishScheduleTotal.reset();
277→    for (const row of republishByStatus) {
278→      this.republishScheduleTotal.labels(row.status).set(parseInt(row.count, 10));
279→    }
280→  }
281→}
