echo "=== Metric names ===" && for f in docker/grafana/alerts/*.json; do echo "--- $(basename $f) ---"; python3 -c "
import json
data = json.load(open('$f'))
for rule in data:
    print(f\"  {rule['title']}\")
    for d in rule.get('data', []):
        expr = d.get('model', {}).get('expr', '')
        if expr:
            print(f\"    PromQL: {expr[:80]}...\")
        conds = d.get('model', {}).get('conditions', [])
        for c in conds:
            params = c.get('evaluator', {}).get('params', [])
            if params:
                print(f\"    Threshold: > {params[0]}\")
"; done && echo "" && echo "=== Placeholder checks ===" && grep -c "GRAFANA_CLOUD_DATASOURCE_UID" docker/grafana/alerts/*.json && grep -c "GRAFANA_ALERTS_FOLDER_UID" docker/grafana/alerts/*.json && echo "" && echo "=== noDataState checks ===" && grep -c '"noDataState": "OK"' docker/grafana/alerts/*.json && echo "" && echo "=== for checks ===" && grep -c '"for": "5m"' docker/grafana/alerts/*.json

