import type { PinningProvider, PinResult, PinStatus } from './types';

/** Timeout for all Kubo RPC requests (10 seconds — ~44x client-side pin p99 of 227ms, generous for large files) */
const REQUEST_TIMEOUT_MS = 10_000;

/**
 * PinningProvider implementation for Kubo RPC API (/api/v0/*).
 *
 * Talks directly to a Kubo node's HTTP API. Suitable for self-hosted
 * Kubo nodes or any IPFS node exposing the Kubo-compatible RPC interface.
 */
export class KuboProvider implements PinningProvider {
  private readonly endpoint: string;
  private readonly authToken?: string;

  constructor(endpoint: string, authToken?: string) {
    // Normalize: strip trailing slash
    this.endpoint = endpoint.replace(/\/+$/, '');
    this.authToken = authToken;
  }

  /**
   * Upload and pin data to the Kubo node.
   * Uses /api/v0/add with pin=true and cid-version=1 for CIDv1.
   */
  async pin(data: Uint8Array, _name?: string): Promise<PinResult> {
    const url = `${this.endpoint}/api/v0/add?pin=true&cid-version=1`;
    const formData = new FormData();
    // Pass typed array directly to Blob (never use .buffer to avoid offset issues)
    const blob = new Blob([data as BlobPart], { type: 'application/octet-stream' });
    formData.append('file', blob);

    const response = await fetch(url, {
      method: 'POST',
      body: formData,
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Kubo add failed: ${response.status} - ${errorText}`);
    }

    // Kubo returns ndjson; for a single file, parse the first (only) line
    const text = await response.text();
    const result = JSON.parse(text) as { Hash: string; Size: string };
    return {
      cid: result.Hash,
      size: parseInt(result.Size, 10),
    };
  }

  /**
   * Remove a pin by CID.
   * Ignores "not pinned" errors for idempotency.
   */
  async unpin(cid: string): Promise<void> {
    const url = `${this.endpoint}/api/v0/pin/rm?arg=${encodeURIComponent(cid)}`;

    const response = await fetch(url, {
      method: 'POST',
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const errorText = await response.text();
      // "not pinned" means already unpinned -- treat as success (idempotent)
      if (errorText.toLowerCase().includes('not pinned')) {
        return;
      }
      throw new Error(`Kubo unpin failed: ${response.status} - ${errorText}`);
    }
  }

  /**
   * Check pin status by CID.
   * Returns 'pinned' on success, 'failed' if the CID is not pinned.
   */
  async status(cid: string): Promise<PinStatus> {
    const url = `${this.endpoint}/api/v0/pin/ls?arg=${encodeURIComponent(cid)}`;

    try {
      const response = await fetch(url, {
        method: 'POST',
        headers: this.buildHeaders(),
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });

      if (!response.ok) {
        return { cid, status: 'failed' };
      }

      return { cid, status: 'pinned' };
    } catch {
      return { cid, status: 'failed' };
    }
  }

  /**
   * Fetch pinned content by CID.
   * Returns the raw bytes of the content.
   */
  async get(cid: string): Promise<Uint8Array> {
    const url = `${this.endpoint}/api/v0/cat?arg=${encodeURIComponent(cid)}`;

    const response = await fetch(url, {
      method: 'POST',
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Kubo cat failed: ${response.status} - ${errorText}`);
    }

    return new Uint8Array(await response.arrayBuffer());
  }

  /** Build auth headers for Kubo requests */
  private buildHeaders(): Record<string, string> {
    if (this.authToken) {
      return { Authorization: `Basic ${this.authToken}` };
    }
    return {};
  }
}

import type { PinningProvider, PinResult, PinStatus } from './types';

/** Fixed upload URL for Pinata file uploads (always this domain, not configurable) */
const UPLOAD_URL = 'https://uploads.pinata.cloud';

/** Timeout for all Pinata API requests (30 seconds — external network, 15x BYO p50 of 2.0s upload) */
const REQUEST_TIMEOUT_MS = 30_000;

/**
 * PinningProvider implementation for Pinata's native v3 API.
 *
 * Pinata deprecated their PSA endpoint (/psa returns 404). Their current API
 * uses proprietary endpoints:
 * - /v3/files for upload and management
 * - /pinning/pinByHash for CID-based pinning
 *
 * Two base URLs are used:
 * - https://uploads.pinata.cloud -- file uploads (fixed, not configurable)
 * - https://api.pinata.cloud -- management operations (list, delete, pinByHash)
 *
 * The `endpoint` constructor param should be the management URL
 * (https://api.pinata.cloud).
 */
export class PinataProvider implements PinningProvider {
  private readonly endpoint: string;
  private readonly authToken: string;
  private readonly gatewayUrl?: string;

  constructor(endpoint: string, authToken: string, gatewayUrl?: string) {
    this.endpoint = endpoint.replace(/\/+$/, '');
    this.authToken = authToken;
    this.gatewayUrl = gatewayUrl?.replace(/\/+$/, '');
  }

  /**
   * Upload and pin data via Pinata's v3 file upload API.
   * POST https://uploads.pinata.cloud/v3/files
   */
  async pin(data: Uint8Array, name?: string): Promise<PinResult> {
    const blob = new Blob([data as BlobPart], { type: 'application/octet-stream' });
    const formData = new FormData();
    formData.append('file', blob, name ?? `cipherbox-${Date.now()}`);

    const response = await fetch(`${UPLOAD_URL}/v3/files`, {
      method: 'POST',
      headers: { Authorization: `Bearer ${this.authToken}` },
      body: formData,
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Pinata upload failed: ${response.status} - ${errorText}`);
    }

    const result = (await response.json()) as {
      data: { id: string; cid: string; size: number };
    };
    return { cid: result.data.cid, size: result.data.size };
  }

  /**
   * Pin an existing CID via Pinata's pinByHash endpoint.
   * Pinata will retrieve the content from the IPFS network and pin it.
   * POST https://api.pinata.cloud/pinning/pinByHash
   */
  async pinByCid(cid: string): Promise<{ cid: string; status: string }> {
    const response = await fetch(`${this.endpoint}/pinning/pinByHash`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${this.authToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ hashToPin: cid }),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Pinata pinByHash failed: ${response.status} - ${errorText}`);
    }

    const result = (await response.json()) as { ipfsHash: string; status: string };
    return { cid: result.ipfsHash, status: result.status };
  }

  /**
   * Remove a pin by CID.
   * Pinata uses file IDs for deletion, so we first look up the file(s)
   * by CID, then delete each one.
   */
  async unpin(cid: string): Promise<void> {
    const listResponse = await fetch(`${this.endpoint}/v3/files?cid=${encodeURIComponent(cid)}`, {
      method: 'GET',
      headers: { Authorization: `Bearer ${this.authToken}` },
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!listResponse.ok) {
      throw new Error(`Pinata list failed: ${listResponse.status}`);
    }

    const listResult = (await listResponse.json()) as {
      data: { files: Array<{ id: string }> };
    };

    for (const file of listResult.data.files) {
      const deleteResponse = await fetch(`${this.endpoint}/v3/files/${file.id}`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${this.authToken}` },
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
      if (!deleteResponse.ok) {
        throw new Error(`Pinata delete failed: ${deleteResponse.status}`);
      }
    }
  }

  /**
   * Check pin status by CID.
   * Queries the Pinata v3 files API and returns 'pinned' if found, 'failed' if not.
   */
  async status(cid: string): Promise<PinStatus> {
    const response = await fetch(`${this.endpoint}/v3/files?cid=${encodeURIComponent(cid)}`, {
      method: 'GET',
      headers: { Authorization: `Bearer ${this.authToken}` },
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) return { cid, status: 'failed' };

    const result = (await response.json()) as {
      data: { files: Array<{ id: string; cid: string }> };
    };

    return {
      cid,
      status: result.data.files.length > 0 ? 'pinned' : 'failed',
    };
  }

  /**
   * Fetch pinned content by CID via Pinata's gateway.
   * Uses the dedicated gateway URL if configured, otherwise the default public gateway.
   */
  async get(cid: string): Promise<Uint8Array> {
    const gateway = this.gatewayUrl ?? 'https://gateway.pinata.cloud';
    const response = await fetch(`${gateway}/ipfs/${encodeURIComponent(cid)}`, {
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      throw new Error(`Pinata gateway fetch failed: ${response.status}`);
    }

    return new Uint8Array(await response.arrayBuffer());
  }
}

import type { PinningProvider, PinResult, PinStatus } from './types';

/** Timeout for all PSA requests (15 seconds — external service, conservative reduction) */
const REQUEST_TIMEOUT_MS = 15_000;

/** PSA pin object from the Pinning Service API response */
interface PsaPinObject {
  requestid: string;
  status: 'queued' | 'pinning' | 'pinned' | 'failed';
  pin: {
    cid: string;
    name?: string;
  };
}

/** PSA list response */
interface PsaListResponse {
  count: number;
  results: PsaPinObject[];
}

/**
 * PinningProvider implementation for the IPFS Pinning Service API (PSA).
 *
 * PSA is a CID-reference-only protocol: it cannot accept raw data uploads.
 * Data must be uploaded to an IPFS node first, then the CID is submitted
 * to the pinning service for retrieval and pinning.
 *
 * Supports: Pinata, web3.storage, Filebase, and any PSA-compatible service.
 */
export class PsaProvider implements PinningProvider {
  private readonly endpoint: string;
  private readonly authToken: string;

  constructor(endpoint: string, authToken: string) {
    // Normalize: strip trailing slash
    this.endpoint = endpoint.replace(/\/+$/, '');
    this.authToken = authToken;
  }

  /**
   * PSA cannot upload raw data. Always throws.
   * Use pinByCid() after uploading via CipherBox relay or a Kubo node.
   */
  async pin(_data: Uint8Array, _name?: string): Promise<PinResult> {
    throw new Error(
      'PsaProvider.pin() cannot upload raw data. Use pinByCid() after uploading via CipherBox relay or Kubo node.'
    );
  }

  /**
   * Pin a CID on the pinning service.
   * The service will retrieve the content from the IPFS network and pin it.
   */
  async pinByCid(
    cid: string,
    name?: string
  ): Promise<{ cid: string; status: PinStatus['status'] }> {
    const url = `${this.endpoint}/pins`;
    const body = {
      cid,
      name: name ?? `cipherbox-${Date.now()}`,
    };

    const response = await fetch(url, {
      method: 'POST',
      headers: this.buildHeaders({ 'Content-Type': 'application/json' }),
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`PSA pin failed: ${response.status} - ${errorText}`);
    }

    const result = (await response.json()) as PsaPinObject;
    return {
      cid: result.pin.cid,
      status: result.status,
    };
  }

  /**
   * Remove a pin by CID.
   * PSA uses requestid for deletion, so we first list pins by CID
   * to find the requestid(s), then delete each one.
   */
  async unpin(cid: string): Promise<void> {
    // First, find the pin request(s) for this CID
    const listUrl = `${this.endpoint}/pins?cid=${encodeURIComponent(cid)}&status=pinned,pinning,queued`;

    const listResponse = await fetch(listUrl, {
      method: 'GET',
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!listResponse.ok) {
      const errorText = await listResponse.text();
      throw new Error(`PSA list for unpin failed: ${listResponse.status} - ${errorText}`);
    }

    const listResult = (await listResponse.json()) as PsaListResponse;

    // Delete each pin request by its requestid
    for (const pin of listResult.results) {
      const deleteUrl = `${this.endpoint}/pins/${encodeURIComponent(pin.requestid)}`;

      const deleteResponse = await fetch(deleteUrl, {
        method: 'DELETE',
        headers: this.buildHeaders(),
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });

      if (!deleteResponse.ok) {
        const errorText = await deleteResponse.text();
        throw new Error(
          `PSA delete pin ${pin.requestid} failed: ${deleteResponse.status} - ${errorText}`
        );
      }
    }
  }

  /**
   * Check pin status by CID.
   * Queries the pinning service for the latest status of a CID.
   */
  async status(cid: string): Promise<PinStatus> {
    const url = `${this.endpoint}/pins?cid=${encodeURIComponent(cid)}&limit=1`;

    const response = await fetch(url, {
      method: 'GET',
      headers: this.buildHeaders(),
      signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    });

    if (!response.ok) {
      return { cid, status: 'failed' };
    }

    const result = (await response.json()) as PsaListResponse;

    if (result.count === 0 || result.results.length === 0) {
      return { cid, status: 'failed' };
    }

    return {
      cid,
      status: result.results[0].status,
    };
  }

  /**
   * PSA does not support content retrieval. Always throws.
   * Use an IPFS gateway to fetch content by CID.
   */
  async get(_cid: string): Promise<Uint8Array> {
    throw new Error('PsaProvider does not support content retrieval. Use an IPFS gateway.');
  }

  /** Build auth headers with Bearer token */
  private buildHeaders(extra?: Record<string, string>): Record<string, string> {
    return {
      Authorization: `Bearer ${this.authToken}`,
      ...extra,
    };
  }
}

import { encryptFile, EncryptedFileResult } from './file-crypto.service';
import { addToIpfs, AddResponse } from '../lib/api/ipfs';
import { useQuotaStore } from '../stores/quota.store';
import { useUploadStore } from '../stores/upload.store';
import { CancelToken } from 'axios';

const MAX_RETRIES = 3;
const RETRY_BASE_DELAY = 500; // 500ms — faster recovery for transient upload failures

export type UploadedFile = {
  cid: string;
  size: number;
  iv: string;
  wrappedKey: string;
  originalName: string;
  originalSize: number;
  encryptionMode: 'GCM' | 'CTR';
};

/**
 * Retry wrapper with exponential backoff.
 * Does not retry cancelled operations.
 */
async function withRetry<T>(
  fn: () => Promise<T>,
  maxRetries: number = MAX_RETRIES,
  baseDelay: number = RETRY_BASE_DELAY
): Promise<T> {
  let lastError: Error = new Error('Retry failed');

  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error as Error;
      // Don't retry if cancelled
      if ((error as Error).message === 'Upload cancelled by user') {
        throw error;
      }
      if (attempt < maxRetries - 1) {
        const delay = baseDelay * Math.pow(2, attempt);
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }

  throw lastError;
}

/**
 * Upload a single file: encrypt then upload to IPFS.
 */
export async function uploadFile(
  file: File,
  userPublicKey: Uint8Array,
  onProgress?: (percent: number) => void,
  cancelToken?: CancelToken
): Promise<UploadedFile> {
  // 1. Encrypt the file
  const encrypted: EncryptedFileResult = await encryptFile(file, userPublicKey);

  // 2. Upload to IPFS with retry
  // Cast to ArrayBuffer for TypeScript 5.9 compatibility (Uint8Array.buffer is ArrayBufferLike)
  const blob = new Blob([encrypted.ciphertext.buffer as ArrayBuffer], {
    type: 'application/octet-stream',
  });
  const result: AddResponse = await withRetry(() => addToIpfs(blob, onProgress, cancelToken));

  return {
    cid: result.cid,
    size: result.size,
    iv: encrypted.iv,
    wrappedKey: encrypted.wrappedKey,
    originalName: file.name,
    originalSize: encrypted.originalSize,
    encryptionMode: encrypted.encryptionMode,
  };
}

/**
 * Upload multiple files sequentially.
 * Pre-checks quota and tracks progress via upload store.
 */
export async function uploadFiles(
  files: File[],
  userPublicKey: Uint8Array
): Promise<UploadedFile[]> {
  const uploadStore = useUploadStore.getState();
  const quotaStore = useQuotaStore.getState();

  // Calculate total size
  const totalSize = files.reduce((sum, f) => sum + f.size, 0);

  // Pre-check quota
  if (!quotaStore.canUpload(totalSize)) {
    throw new Error(
      `Not enough space (${Math.round(quotaStore.usedBytes / 1024 / 1024)} of ${Math.round(quotaStore.limitBytes / 1024 / 1024)}MB used)`
    );
  }

  uploadStore.startUpload(files.length);
  const results: UploadedFile[] = [];

  try {
    // Sequential uploads per CONTEXT.md decision
    for (const file of files) {
      const cancelSource = useUploadStore.getState().cancelSource;
      if (useUploadStore.getState().status === 'cancelled') {
        throw new Error('Upload cancelled by user');
      }

      uploadStore.setEncrypting(file.name);

      const result = await uploadFile(
        file,
        userPublicKey,
        (percent) => uploadStore.setUploading(file.name, percent),
        cancelSource?.token
      );

      results.push(result);
      uploadStore.fileComplete();
    }

    uploadStore.setSuccess();
    return results;
  } catch (error) {
    const message = (error as Error).message;
    if (message !== 'Upload cancelled by user') {
      uploadStore.setError(message);
      console.error('Upload failed:', error);
    }
    throw error;
  } finally {
    // Refresh quota from server (authoritative source after atomic upload)
    await useQuotaStore.getState().fetchQuota();
  }
}

