    });

    it('uses fallback URL when primary resolve fails', async () => {
      const testBuffer = new Uint8Array([10, 20, 30]).buffer;
      mockFetch
        .mockRejectedValueOnce(new Error('ECONNREFUSED'))
        .mockRejectedValueOnce(new Error('ECONNREFUSED'))
        .mockRejectedValueOnce(new Error('ECONNREFUSED'))
